const src = $('Build Prompts').all();
const outs = $input.all();
const triage = {};
src.forEach((it, i) => {
  const o = outs[i]?.json ?? {};
  const text = o.message?.content ?? '';
  let fp = null;
  let note = '';
  if (text) {
    const m = String(text).match(/\{[\s\S]*\}/);
    try {
      const p = JSON.parse(m ? m[0] : text);
      const n = parseInt(p.false_positive_percent ?? p.fp_likelihood, 10);
      fp = Number.isNaN(n) ? null : Math.max(0, Math.min(100, n));
      note = String(p.summary ?? '').replace(/\s+/g, ' ').trim().slice(0, 300);
    } catch (e) {
      note = '';
    }
  }
  if (!note) note = o.error ? 'triage unavailable' : 'triage output unparseable';
  triage[it.json.finding_key] = { fp_likelihood: fp, note };
});
return [{ json: { triage, triaged: src.length } }];

const MODEL = 'OLLAMA_MODEL';
const SYSTEM = [
  'You triage automated scanner output for a penetration tester during an authorised external attack surface assessment.',
  'Judge only from the evidence given. Reply with JSON only, exactly this shape:',
  '{"false_positive_percent": <integer 0-100>, "summary": "<one sentence, max 25 words>"}',
  'false_positive_percent: 0 means the finding is certainly real and exploitable as described, 100 means it is certainly scanner noise.',
  'summary: what the issue is and why it matters, or why it is probably noise.'
].join('\n');
return $input.all().map((it) => {
  const f = it.json;
  const user = [
    `Source tool: ${f.source}`,
    `Template: ${f.template_id}`,
    `Name: ${f.name}`,
    `Severity: ${f.severity}`,
    `Matched at: ${f.matched_at}`,
    `Evidence: ${String(f.detail || 'none').slice(0, 600)}`
  ].join('\n');
  return { json: {
    finding_key: f.finding_key,
    body: {
      model: MODEL,
      stream: false,
      think: false,
      format: 'json',
      keep_alive: '15m',
      options: { temperature: 0.1, num_predict: 200 },
      messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: user }]
    }
  } };
});
